/* Map interactions share the same allocations as the coloured polygons. */
let impactRows=[];
function impactSummary(){
 const lives=showLives?(hypothesis&&expandedMortality?expandedMortality:GazaSelection.selectCommunes(communes,center,fatalities,turf)).selected:[];
 const injuriesRows=showInjuries?injurySelection?.selected||[]:[];
 const merged=new Map();
 for(const [kind,rows] of [['lives',lives],['injured',injuriesRows]])for(const row of rows){const code=row.feature.properties.code,item=merged.get(code)||{feature:row.feature,population:row.population,lives:0,injured:0};item[kind]=row.represented;merged.set(code,item);}
 // Lives lost first, in decreasing order, then injuries in decreasing order.
 return [...merged.values()].sort((a,b)=>b.lives-a.lives||b.injured-a.injured||a.feature.properties.nom.localeCompare(b.feature.properties.nom,'fr'));
}
function communePopup(feature,latlng){
 const row=impactRows.find(r=>r.feature.properties.code===feature.properties.code),content=document.createElement('div');content.className='commune-popup';
 const title=document.createElement('strong');title.textContent=feature.properties.nom;content.append(title);
 const p=document.createElement('p');p.textContent=Number.isFinite(feature.properties.population)?t('{n} habitants',{n:fmt(feature.properties.population)})+(feature.properties.populationYear?' ('+feature.properties.populationYear+')':''):t('Population indisponible');content.append(p);
 if(feature.properties.approx){const zone=document.createElement('small');zone.className='popup-approx';zone.textContent=t('Contour approché : la zone la plus proche de cette localité.');content.append(zone);}
 for(const [label,key,visible] of [[t('Vies perdues'),'lives',showLives],[t('Blessés'),'injured',showInjuries]]){const line=document.createElement('p');line.className=key==='lives'?'text-lives':'text-injuries';const count=row?.[key]||0;line.textContent=label+(window.LANG==='en'?': ':' : ')+(visible?t('{n} personnes représentées',{n:fmt(count)})+(feature.properties.population?' · '+fmt(count/feature.properties.population*100,1)+(window.LANG==='en'?'%':' %'):''):t('couche masquée'));content.append(line);}
 const note=document.createElement('small');note.textContent=t('Équivalence démographique avec Gaza, pas un bilan local.');if(hypothesis)note.textContent+=t(' Hypothèse de 680 000 non confirmée.');content.append(note);
 L.popup({maxWidth:window.matchMedia('(max-width:650px)').matches?200:290,autoPan:true}).setLatLng(latlng).setContent(content).openOn(map);
}
window.refreshMapExtras=()=>{
 $('color-key').querySelector('.key-red').parentElement.hidden=!showLives||level!=='communes';$('color-key').querySelector('.key-yellow').parentElement.hidden=!showInjuries||level!=='communes';$('color-key').querySelector('.key-grey').parentElement.hidden=!showDamage;$('color-key').querySelector('.key-population').parentElement.hidden=!showPopulation;$('color-key').querySelector('.key-hatch').parentElement.hidden=!showLives||!showInjuries||level!=='communes';
 $('color-key').querySelector('.key-grey').parentElement.lastChild.textContent='≈ '+fmt(damageData[damageKind].ratio*100)+(window.LANG==='en'?'% · ':' % · ')+(damageKind==='affected'?t('bâtiments détruits ou endommagés*'):t('bâtiments détruits*'));
 impactRows=[];if(level!=='communes'||communeState!=='ready')return;
 impactRows=impactSummary();
 // The commune lists live in the victims panel; these rows serve map clicks and popups.
};
