$('search-city').addEventListener('input',()=>{clearTimeout(searchTimer);searchAbort?.abort();const request=++searchSequence,q=$('search-city').value.trim();$('city-results').replaceChildren();$('city-results').hidden=true;$('search-feedback').textContent='';if(q.length<2)return;searchTimer=setTimeout(async()=>{searchAbort=new AbortController();$('search-feedback').textContent=t('Recherche…');let french=[],failed=false;try{const params=new URLSearchParams({...(/^\d{5}$/.test(q)?{codePostal:q}:{nom:q}),fields:'nom,code,population,centre,codesPostaux,departement',boost:'population',limit:8});const response=await fetch('https://geo.api.gouv.fr/communes?'+params,{signal:searchAbort.signal});if(!response.ok)throw Error();french=await response.json();}catch(e){if(e.name==='AbortError')return;failed=true;}if(request!==searchSequence)return;await Promise.race([loadEuropePlaces(),new Promise(r=>setTimeout(r,4000))]);if(request!==searchSequence)return;extraPlaces??=[...placeRows(window.MIDDLE_EAST_DATA?.places||[]),...placeRows(europePlaces||[])];const local=[...placeRows(window.SWISS_DATA?.places||[]),...window.OVERSEAS_INDEX.places.map(p=>({properties:p})),...extraPlaces].filter(f=>normalize(f.properties.nom).includes(normalize(q))).sort((a,b)=>(b.properties.population||0)-(a.properties.population||0)).slice(0,8).map(f=>({...f.properties,centre:f.properties.centre||turf.pointOnFeature(f).geometry}));const arr=arrondissementPlaces.filter(p=>normalize(p.nom).includes(normalize(q))||p.codesPostaux.includes(q)).map(p=>({...p,nom:p.nom.replace(' Arrondissement',''),arrondissement:true}));const choices=[...new Map([...local,...french,...arr].filter(p=>{const c=p.centre?.coordinates;return Array.isArray(c)&&Number.isFinite(c[0])&&Number.isFinite(c[1])&&Math.abs(c[0])<=180&&Math.abs(c[1])<=80;}).map(p=>[p.code,p])).values()].sort((a,b)=>{const exact=p=>normalize(p.nom)===normalize(q);return Number(exact(b))-Number(exact(a))||Number(Boolean(b.arrondissement))-Number(Boolean(a.arrondissement))||(a.arrondissement&&b.arrondissement?a.nom.localeCompare(b.nom,'fr',{numeric:true}):(b.population||0)-(a.population||0));}).slice(0,30);$('search-feedback').textContent=failed?t('La recherche des communes françaises ne répond pas. Résultats limités aux autres pays, à l’outre-mer et aux arrondissements.'):choices.length?'':t('Aucune commune trouvée.');for(const p of choices){const button=document.createElement('button');const label=document.createElement('strong'),detail=document.createElement('small');label.textContent=p.nom;detail.textContent=p.country&&p.country!=='FR'?countryName(p.country):p.nom==='Paris'?t('Tous les arrondissements · Paris'):p.codesPostaux?.length?p.codesPostaux.join(' · ')+(p.departement?.nom?' · '+p.departement.nom:''):t('France · outre-mer');button.append(label,detail);button.onclick=()=>{++searchSequence;searchAbort?.abort();$('search-city').value=p.nom;$('city-results').hidden=true;$('search-feedback').textContent='';placeCity(p.centre.coordinates[1],p.centre.coordinates[0]);};$('city-results').append(button);}$('city-results').hidden=!choices.length;},300);});
